## Code Example
```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.isWord = false;
    this.passCount = 0;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
    this.wordSet = new Set();
  }

  insert(word) {
    if (this.wordSet.has(word)) return;
    this.wordSet.add(word);
    let node = this.root;
    for (const char of word) {
      if (!node.next.has(char)) {
        node.next.set(char, new TrieNode());
      }
      node = node.next.get(char);
      node.passCount++;
    }
    node.isWord = true;
  }

  countPrefix(prefix) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return 0;
      node = node.next.get(char);
    }
    return node.passCount;
  }

  listWithPrefix(prefix, limit) {
    let node = this.root;
    for (const char of prefix) {
      if (!node.next.has(char)) return [];
      node = node.next.get(char);
    }
    const result = [];
    this.dfs(node, prefix, result, limit);
    return result;
  }

  dfs(node, current, result, limit) {
    if (result.length >= limit) return;
    if (node.isWord) {
      result.push(current);
    }
    const sortedKeys = Array.from(node.next.keys()).sort();
    for (const char of sortedKeys) {
      this.dfs(node.next.get(char), current + char, result, limit);
    }
  }
}
```

## Why This Is Asked

This question tests stability, memory constraints, and practical trade-offs between sorting algorithms. It asks for a concrete approach rather than a generic answer.

## Key Concepts

- Stable sorting
- Bottom-up merge sort
- Time/space complexity: O(n log n) time, O(n) extra space

## Code Example

```javascript
function stableSort(arr){
  const n = arr.length; 
  const aux = new Array(n);
  for (let width = 1; width < n; width *= 2){
    for (let i = 0; i < n; i += width * 2){
      const left = i;
      const mid = Math.min(i + width, n);
      const right = Math.min(i + width * 2, n);
      let p = left, q = mid, k = left;
      while (p < mid && q < right){
        if (arr[p].score <= arr[q].score) aux[k++] = arr[p++];
        else aux[k++] = arr[q++];
      }
      while (p < mid) aux[k++] = arr[p++];
      while (q < right) aux[k++] = arr[q++];
      for (let t = left; t < right; t++) arr[t] = aux[t];
    }
  }
  return arr;
}
```

